package com.dizzy.remake.core

import java.io.ByteArrayOutputStream
import java.util.zip.Inflater

/**
 * Exact 17-byte metatile definitions used by the 50 original locations.
 * Only ROM ranges reachable through the 13 proven location metatile bases are
 * embedded; definitions are still indexed by the original cell ID.
 */
object OriginalMetatileCatalog {
    data class SetData(val bank:Int,val baseCpu:Int,val maxCellId:Int,val bytes:ByteArray)

    private const val ENCODED =
        "" +
        "" +
        "" +
        "" +
        "" +
        "28Deyy9eSix378k3iH999fo5Yx+H1F5/+uk1k94n8r8A/JzP7Q=="

    private val sets:List<SetData> by lazy { decodeSets() }

    fun definition(locationKey:Int,cellId:Int):OriginalMetatile {
        require(locationKey in 0 until OriginalLocationCatalog.COUNT)
        val location=OriginalLocationCatalog[locationKey]
        val set=sets.firstOrNull { it.bank==location.metatileBank && it.baseCpu==location.metatileBaseCpu }
            ?: error("Missing original metatile set")
        require(cellId in 0..set.maxCellId)
        return OriginalMetatile.decode(set.bytes,cellId*OriginalMetatile.BYTE_SIZE)
    }

    fun at(locationKey:Int,row:Int,column:Int):OriginalMetatile =
        definition(locationKey,OriginalMapCellCatalog.cellId(locationKey,row,column))

    fun setCount():Int=sets.size

    private fun decodeSets():List<SetData> {
        val packed=inflate(decodeBase64(ENCODED))
        require(packed.size==32222)
        require(packed[0].toInt()==0x44 && packed[1].toInt()==0x5A &&
                packed[2].toInt()==0x4D && packed[3].toInt()==0x54)
        require((packed[4].toInt() and 0xff)==1)
        val count=packed[5].toInt() and 0xff
        require(count==13)
        var p=6
        val result=ArrayList<SetData>(count)
        repeat(count) {
            val bank=packed[p++].toInt() and 0xff
            val base=(packed[p++].toInt() and 0xff) or ((packed[p++].toInt() and 0xff) shl 8)
            val maxId=packed[p++].toInt() and 0xff
            val size=(maxId+1)*OriginalMetatile.BYTE_SIZE
            result+=SetData(bank,base,maxId,packed.copyOfRange(p,p+size))
            p+=size
        }
        require(p==packed.size)
        require(result.map{it.bank to it.baseCpu}.toSet().size==13)
        return result
    }

    private fun inflate(compressed:ByteArray):ByteArray {
        val inflater=Inflater()
        inflater.setInput(compressed)
        val out=ByteArrayOutputStream(32222)
        val buffer=ByteArray(4096)
        while(!inflater.finished()) {
            val n=inflater.inflate(buffer)
            require(n>0 || !inflater.needsInput())
            if(n>0) out.write(buffer,0,n)
        }
        inflater.end()
        return out.toByteArray()
    }

    private fun decodeBase64(s:String):ByteArray {
        val alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        require(s.length%4==0)
        val padding=(if(s.endsWith("==")) 2 else if(s.endsWith("=")) 1 else 0)
        val out=ByteArray(s.length/4*3-padding)
        var oi=0
        var i=0
        while(i<s.length) {
            val a=alphabet.indexOf(s[i])
            val b=alphabet.indexOf(s[i+1])
            val c=if(s[i+2]=='=') 0 else alphabet.indexOf(s[i+2])
            val d=if(s[i+3]=='=') 0 else alphabet.indexOf(s[i+3])
            require(a>=0 && b>=0 && c>=0 && d>=0)
            val v=(a shl 18) or (b shl 12) or (c shl 6) or d
            if(oi<out.size) out[oi++]=(v ushr 16).toByte()
            if(oi<out.size) out[oi++]=(v ushr 8).toByte()
            if(oi<out.size) out[oi++]=v.toByte()
            i+=4
        }
        require(oi==out.size)
        return out
    }
}
